WITH ranked AS (SELECT * FROM sessions QUALIFY ROW_NUMBER() OVER (PARTITION BY customer_id, browser ORDER BY started_at DESC, id) = 1) SELECT customer_id, browser, COUNT(DISTINCT customer_id) AS distinct_customer_ids, MIN(started_at) AS first_started_at, COUNT(DISTINCT id) AS distinct_ids, SIZE(COLLECT_SET(device)) AS num_devices FROM ranked GROUP BY customer_id, browser ORDER BY browser NULLS FIRST
